country_event = {
	id = bio.1000

	is_triggered_only = yes
	hide_window = yes

	immediate = {
		set_variable = {
			which = num_evopred_situations_ran
			value = 1
		}
		set_variable = {
			which = smorgasblorg_phenotypes
			value = 0
		}
		start_situation = {
			type = evolutionary_predators_situation
			target = root
		}
		capital_scope = {
			add_modifier = { modifier = genetic_soup }
		}
	}
}

situation_event = {
	id = bio.1001

	is_triggered_only = yes
	hide_window = yes

	immediate = {
		owner = { set_evopred_flags = yes }
	}
}

